"use client";

import { useEffect, useState, type FormEvent, type ReactNode } from "react";
import { LockKeyhole } from "lucide-react";

import { Button } from "@/components/ui/button";
import { api, message, type SessionInfo } from "@/lib/task-api";

export const inputClass = "w-full rounded-lg border border-input bg-background px-3 py-2 text-sm outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/40 disabled:opacity-50";

export function SessionBoundary({ children }: { children: ReactNode }) {
  const [session, setSession] = useState<SessionInfo | null>(null);
  const [token, setToken] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [reload, setReload] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    void api<SessionInfo>("/auth/session", { signal: controller.signal }).then(setSession).catch((error: unknown) => {
      if (!controller.signal.aborted) setError(message(error));
    });
    const expired = () => {
      setSession({ enabled: true, authenticated: false, mode: "local_single_user" });
      setError("Your local session has expired. Unlock the workspace again.");
    };
    window.addEventListener("agentforge-session-expired", expired);
    return () => {
      controller.abort();
      window.removeEventListener("agentforge-session-expired", expired);
    };
  }, [reload]);

  async function unlock(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setBusy(true);
    setError("");
    try {
      await api<void>("/auth/session", { method: "POST", headers: { Authorization: `Bearer ${token}` } });
      setToken("");
      setSession(await api<SessionInfo>("/auth/session"));
    } catch (error) {
      setError(message(error));
    } finally {
      setBusy(false);
    }
  }

  if (session?.authenticated) {
    return (
      <>
        <div className="mb-8 flex flex-wrap items-center justify-between gap-3 border-b pb-4 text-sm">
          <p className="text-muted-foreground">{session.user?.display_name ?? "Local workspace"} <span className="mx-2" aria-hidden="true">·</span> Local session</p>
          <Button variant="ghost" size="sm" disabled={busy} onClick={async () => {
            setBusy(true);
            try {
              await api<void>("/auth/logout", { method: "POST" });
              setSession({ enabled: true, authenticated: false, mode: "local_single_user" });
            } catch (error) { setError(message(error)); }
            finally { setBusy(false); }
          }}>Lock workspace</Button>
        </div>
        {error ? <p role="alert" className="mb-5 text-sm text-destructive">{error}</p> : null}
        {children}
      </>
    );
  }

  return (
    <section className="mx-auto max-w-lg space-y-6 py-8" aria-labelledby="session-title">
      <LockKeyhole aria-hidden="true" className="size-7 text-muted-foreground" />
      <div className="space-y-2">
        <h1 id="session-title" className="text-2xl font-semibold tracking-tight">{session?.enabled ? "Unlock your workspace" : session ? "Set up local access" : "Connecting to your workspace"}</h1>
        <p className="text-sm leading-relaxed text-muted-foreground">{session?.enabled ? "Enter the bootstrap token from your private API configuration. Your local session expires after the configured duration." : session ? "Task access is disabled until a local identity and bootstrap token are configured. Follow docs/phase-3.md, restart the API, then reconnect." : "Checking the local API and session configuration."}</p>
      </div>
      {!session && !error ? <div aria-label="Loading session" className="h-10 rounded-lg bg-muted" /> : null}
      {session?.enabled ? (
        <form onSubmit={unlock} className="space-y-4">
          <div className="space-y-2">
            <label htmlFor="bootstrap-token" className="text-sm font-medium">Bootstrap token</label>
            <input id="bootstrap-token" type="password" autoComplete="off" required minLength={32} maxLength={512} value={token} onChange={(event) => setToken(event.target.value)} className={inputClass} aria-describedby="token-help" disabled={busy} />
            <p id="token-help" className="text-xs text-muted-foreground">Local access only. API restart or session expiry requires unlocking again.</p>
          </div>
          <Button type="submit" disabled={busy}>{busy ? "Unlocking…" : "Unlock workspace"}</Button>
        </form>
      ) : null}
      {error ? <p role="alert" className="text-sm text-destructive">{error}</p> : null}
      {!session?.enabled ? <Button variant="outline" onClick={() => { setError(""); setSession(null); setReload((value) => value + 1); }}>Reconnect</Button> : null}
    </section>
  );
}
/** Public HTTP shapes. Identity and effective authorization stay on the server. */
export type SessionInfo = {
  enabled: boolean;
  authenticated: boolean;
  mode: string;
  user?: { id: string; display_name: string };
};
export type Project = { id: string; name: string; created_at: string };
export type Task = {
  id: string;
  project_id: string;
  goal: string;
  status: string;
  max_cost_usd: string;
  max_wall_time_sec: number;
  created_at: string;
  updated_at: string;
  cancel_requested_at: string | null;
  final_summary: string | null;
  final_result: Record<string, unknown> | null;
  error_code: string | null;
  event_sequence: number;
};
export type TaskStep = {
  id: string;
  step_key: string;
  agent_type: string;
  definition_version: number;
  objective: string;
  acceptance_criteria: string[];
  depends_on: string[];
  status: string;
  agent_run_id: string | null;
};
export type TaskEvent = {
  task_id: string;
  sequence: number;
  event_type: string;
  payload: Record<string, unknown>;
  created_at: string;
};
export type AgentRun = {
  id: string;
  status: string;
  definition_sha256?: string;
  definition_version_id?: string;
  effective_permissions_json?: Record<string, unknown>;
  effective_budget_json?: Record<string, unknown>;
  reserved_cost_usd?: string;
  measured_cost_usd?: string | null;
  error_code?: string | null;
  started_at?: string;
  finished_at?: string | null;
};
export type Source = {
  id: string;
  url: string;
  title: string;
  excerpt: string;
  source_type: "search" | "webpage";
  fetch_status: "SEARCH_ONLY" | "FETCHED" | "FAILED";
  retrieved_at: string;
  error_code: string | null;
};
export type Artifact = {
  id: string;
  kind: string;
  filename: string;
  mime_type: string;
  byte_size: number;
  sha256: string;
  created_at: string;
};

export class ApiError extends Error {
  constructor(public status: number, message: string) {
    super(message);
  }
}

const friendlyErrors: Record<string, string> = {
  session_required: "Your local session has expired. Unlock the workspace again.",
  session_identity_unavailable: "The configured local identity is unavailable. Check local setup.",
  invalid_bootstrap_token: "The bootstrap token was not accepted. Use the token in your private API configuration.",
  local_auth_not_configured: "Local access has not been configured. Follow the local setup instructions.",
  local_identity_not_provisioned: "Provision the configured local identity before unlocking the workspace.",
  task_not_found: "This task is unavailable for the current workspace.",
  artifact_unavailable: "The report file is unavailable. Try downloading it again later.",
};

export async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const response = await fetch(`/api/v1${path}`, {
    ...init,
    cache: "no-store",
    credentials: "same-origin",
    headers: { ...(init.body ? { "Content-Type": "application/json" } : {}), ...init.headers },
  });
  if (!response.ok) {
    const body = await response.json().catch(() => null) as { detail?: unknown } | null;
    const detail = typeof body?.detail === "string" ? body.detail : "";
    if (response.status === 401 && path !== "/auth/session") {
      window.dispatchEvent(new Event("agentforge-session-expired"));
    }
    throw new ApiError(response.status, friendlyErrors[detail] ??
      (response.status === 422 ? "Check the goal, budget and allowed domains, then try again." :
        `The request could not be completed (HTTP ${response.status}). Try again.`));
  }
  return response.status === 204 ? undefined as T : await response.json() as T;
}

export const terminalStatuses = new Set(["COMPLETED", "PARTIAL", "FAILED", "CANCELLED"]);
export const eventTypes = ["task.created", "task.status", "task.cancel_requested", "task.plan.created",
  "task.step.updated", "subagent.started", "subagent.finished", "model.started", "model.finished", "tool.started", "tool.finished",
  "task.verified", "task.recovered", "task.finished"];
export function statusLabel(status: string): string {
  return status.toLowerCase().replaceAll("_", " ").replace(/^./, (letter) => letter.toUpperCase());
}
export function formatDate(value: string): string {
  return new Date(value).toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" });
}
export function message(error: unknown): string {
  return error instanceof Error ? error.message : "Could not reach the API. Check that the local server is running.";
}
export function publicSourceUrl(value: string): string | undefined {
  try {
    const url = new URL(value);
    const host = url.hostname.toLowerCase();
    const publicSyntax = host.includes(".") && !/^[\d.]+$/.test(host) && !host.includes(":") &&
      !host.endsWith(".local") && !host.endsWith(".internal") && !host.endsWith(".localhost");
    return url.protocol === "https:" && publicSyntax && !url.username && !url.password &&
      (!url.port || url.port === "443") ? url.href : undefined;
  } catch {
    return undefined;
  }
}

